#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/types.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// FontDialog's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/font_dialog.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The font OK or Apply last took (initially 9-unit Carlito, like Windows Forms' default); not the dialog's own text font (G1). A view, since OK and Apply move it. A write also resets the selection to it and marks the font as set from code; an invalid FontSpec throws std::invalid_argument.
template <typename Declaring>
struct FontDialogFontCapability {
    PropertyView<FontSpec, FontDialogFontCapability<Declaring>> font;

    static void assign(FontDialogFontCapability& capability, FontSpec incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.font), std::move(incoming));
    }

    static FontSpec read(const FontDialogFontCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        FontSpec current = control.read_view(capability.font);
        return current;
    }
};

// Whether the Apply button is shown.
template <typename Declaring>
struct FontDialogShowApplyCapability {
    PropertyCell<bool, FontDialogShowApplyCapability<Declaring>> show_apply{true};

    static void assign(FontDialogShowApplyCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.show_apply), incoming);
        if (!capability.show_apply.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.show_apply));
    }
};

// The preview text; invalid UTF-8 throws std::invalid_argument.
template <typename Declaring>
struct FontDialogPreviewTextCapability {
    PropertyCell<std::string, FontDialogPreviewTextCapability<Declaring>> preview_text{"AaBbYyZz 0123"};

    static void assign(FontDialogPreviewTextCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.preview_text), incoming);
        if (!capability.preview_text.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.preview_text));
    }
};

// Every FontDialog capability, in the order the declaring class takes them.
template <typename Declaring>
struct FontDialogCapabilities : public FontDialogFontCapability<Declaring>,
                                public FontDialogShowApplyCapability<Declaring>,
                                public FontDialogPreviewTextCapability<Declaring> {};

} // namespace gui_forms
